class Solution {
public:
    int isPrefixOfWord(string sentence, string searchWord) {
        int n = sentence.size();
        int m = searchWord.size();
        int wordIndex = 1;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && sentence[j] != ' ') j++;
            int wordLen = j - i;
            if (wordLen >= m) {
                bool match = true;
                for (int k = 0; k < m; k++) {
                    if (sentence[i + k] != searchWord[k]) {
                        match = false;
                        break;
                    }
                }
                if (match) return wordIndex;
            }
            wordIndex++;
            i = j + 1;
        }
        return -1;
    }
};
